   // --- Sandbox helpers ----------------------------------------------------

   // Resolved SandboxOption handles, keyed by sandbox name. getOptionByName is
   // a linear scan over every registered option and was called several times
   // per physics substep; the handle itself is stable for a world session, so
   // we resolve it once and reuse it. The current value is still re-read from
   // the cached handle on every call, so a mid-session value change is picked
   // up exactly as before -- only the lookup is cached, not the value. The
   // cache is dropped on the existing ~60-tick updateModOptions cadence so a
   // late-registered option (or one not present at first touch) is re-resolved.
   private final HashMap<String, SandboxOption> sandboxHandleCache = new HashMap<>();
   private final java.util.HashSet<String> sandboxHandleMisses = new java.util.HashSet<>();

   private SandboxOption resolveSandboxOption(String key) {
      SandboxOption cached = this.sandboxHandleCache.get(key);
      if (cached != null) {
         return cached;
      }
      if (this.sandboxHandleMisses.contains(key)) {
         return null;
      }
      SandboxOption opt = SandboxOptions.instance.getOptionByName(key);
      if (opt == null) {
         this.sandboxHandleMisses.add(key);
         return null;
      }
      this.sandboxHandleCache.put(key, opt);
      return opt;
   }

   private float getSandboxOption(String key, float fallback) {
      SandboxOption opt = this.resolveSandboxOption(key);
      if (opt == null) {
         return fallback;
      }
      String raw = opt.asConfigOption().getValueAsString();
      float parsed;
      try {
         parsed = (float)Double.parseDouble(raw);
      } catch (NumberFormatException nfe) {
         DebugLog.log("[BetterVehicleDynamics] sandbox key " + key + " not numeric ('" + raw + "'); using " + fallback);
         return fallback;
      }
      if (Float.isNaN(parsed)) {
         DebugLog.log("[BetterVehicleDynamics] sandbox key " + key + " was NaN; using " + fallback);
         return fallback;
      }
      return parsed;
   }

   private boolean getSandboxOptionBoolean(String key, boolean fallback) {
      SandboxOption opt = this.resolveSandboxOption(key);
      if (opt == null) {
         return fallback;
      }
      return (Boolean)opt.asConfigOption().getValueAsObject();
   }

   private KahluaTableImpl bvdBridge() {
      return (KahluaTableImpl)LuaManager.env.rawget("BetterVehicleDynamicsMod");
   }

   // Read a numeric field from a Kahlua row, falling back to a caller-chosen
   // default when the row is null or the field is absent / non-numeric.
   // KahluaTableImpl.rawgetFloat returns -1 for a missing key, which would be
   // a real (catastrophic) grip multiplier here, so the lookup is explicit.
   private static float bridgeFieldOr(KahluaTableImpl row, String field, float fallback) {
      if (row == null) {
         return fallback;
      }
      Object v = row.rawget(field);
      if (v instanceof Double d) {
         return d.floatValue();
      }
      if (v instanceof Float f) {
         return f;
      }
      return fallback;
   }

   // Strip a trailing run of ASCII digits so distinct tire tiers collapse to
   // one profile family (e.g. "ModernTire2" -> "ModernTire"). Returns the
   // input unchanged when it has no trailing digits or is null/empty.
   private static String tireFamilyKey(String itemType) {
      if (itemType == null) {
         return "";
      }
      int end = itemType.length();
      while (end > 0 && itemType.charAt(end - 1) >= '0' && itemType.charAt(end - 1) <= '9') {
         end--;
      }
      return end == itemType.length() ? itemType : itemType.substring(0, end);
   }

   // Memoised wrapper around tireFamilyKey: the substring scan is done at
   // most once per distinct raw item type for the life of this controller,
   // not every physics tick. Same value tireFamilyKey would return.
   private String tireFamilyKeyCached(String itemType) {
      if (itemType == null) {
         return "";
      }
      String cached = this.tireFamilyCache.get(itemType);
      if (cached != null) {
         return cached;
      }
      String resolved = tireFamilyKey(itemType);
      this.tireFamilyCache.put(itemType, resolved);
      return resolved;
   }

   // Reporting-only readout of this tick's effective grip + load figures.
   // Written ONLY when this controller's vehicle is the local player's
   // current vehicle (a non-driving / remote controller never writes), so
   // the Lua panel always reflects the car the player is actually in. The
   // Kahlua table is allocated once and reused, so there is no per-tick
   // allocation. Nothing reads these fields back into the physics.
   // Render-independent skid-mark expiry. PZ's floor-splat *render* lives
   // in a decompiled engine class the patch toolchain can't recompile, so
   // expiry is done here instead: every ~1.5s while a vehicle is updating,
   // drop BVD tyre-mark splats (types 21-24) older than the configured
   // window from the chunks around the vehicle and invalidate those chunk
   // textures so they visually clear. Blood splats are never touched.
   private void bvdPruneSkidMarks() {
      long nowMs = System.currentTimeMillis();
      if (nowMs - this.bvdSkidPruneMs < 1500L) {
         return;
      }
      this.bvdSkidPruneMs = nowMs;
      if (this.cc.vehicleObject == null || IsoWorld.instance == null || IsoWorld.instance.currentCell == null) {
         return;
      }
      float worldAge = (float)GameTime.getInstance().getWorldAgeHours();
      float win = Splat.TIREMARK_FADE_HOURS;
      int cx = PZMath.coorddivision(this.cc.vehicleObject.getXi(), 8);
      int cy = PZMath.coorddivision(this.cc.vehicleObject.getYi(), 8);

      for (int dy = -1; dy <= 1; dy++) {
         for (int dx = -1; dx <= 1; dx++) {
            IsoChunk ch = IsoWorld.instance.currentCell.getChunk(cx + dx, cy + dy);
            if (ch == null) {
               continue;
            }

            java.util.ArrayList<zombie.iso.IsoFloorBloodSplat> keep = null;
            int removed = 0;
            int count = ch.floorBloodSplats.size();
            for (int i = 0; i < count; i++) {
               zombie.iso.IsoFloorBloodSplat s = ch.floorBloodSplats.get(i);
               boolean expire = s.type >= Splat.TIREMARK_TYPE_MIN
                  && s.type <= Splat.TIREMARK_TYPE_MAX
                  && worldAge - s.worldAge >= win;
               if (expire) {
                  if (keep == null) {
                     keep = new java.util.ArrayList<>();
                     for (int k = 0; k < i; k++) {
                        keep.add(ch.floorBloodSplats.get(k));
                     }
                  }
                  removed++;
                  ch.floorBloodSplatsFade.remove(s);
               } else if (keep != null) {
                  keep.add(s);
               }
            }

            if (removed > 0) {
               ch.floorBloodSplats.clear();
               for (int i = 0; i < keep.size(); i++) {
                  ch.floorBloodSplats.add(keep.get(i));
               }
               ch.invalidateRenderChunkLevels(1L);
            }
         }
      }
   }

   // Server/host-authoritative safety net: if this vehicle's physics height
   // has sunk implausibly far below its OWN current level's floor, snap it
   // back onto that floor. Mitigates the "vehicle sucked into the ground"
   // MP desync class. Generic + frozen: all numbers come from the Lua
   // BetterVehicleDynamicsMod.stabilityGuard policy (sandbox-driven); when
   // that policy is absent or disabled this is an immediate NO-OP and the
   // build is byte-identical to before. The floor is recomputed every call
   // from the vehicle's CURRENT level, never a stale saved Z.
   private void bvdStabilityGuard() {
      // Only the side that owns this vehicle's Bullet physics may correct
      // it: never a dedicated server (Bullet is not local there), never a
      // remotely-driven vehicle (slaved to the network).
      if (GameServer.server) {
         return;
      }
      if (this.cc.vehicleObject == null
         || this.cc.vehicleObject.isNetPlayerAuthorization(BaseVehicle.Authorization.Remote)) {
         return;
      }

      KahluaTableImpl bridge = this.bvdBridge();
      Object rawGuard = (bridge == null) ? null : bridge.rawget("stabilityGuard");
      KahluaTableImpl sg = (rawGuard instanceof KahluaTableImpl) ? (KahluaTableImpl)rawGuard : null;
      if (sg == null || bridgeFieldOr(sg, "enabled", 0.0F) < 0.5F) {
         this.bvdSinkTicks = 0;
         if (this.bvdGuardCooldown > 0) {
            this.bvdGuardCooldown--;
         }
         return;
      }

      float sinkDepth = bridgeFieldOr(sg, "sinkDepth", 1.0F);
      int dwellTicks = (int)bridgeFieldOr(sg, "dwellTicks", 5.0F);
      int cooldownTicks = (int)bridgeFieldOr(sg, "cooldownTicks", 60.0F);

      if (this.bvdGuardCooldown > 0) {
         this.bvdGuardCooldown--;
      }

      // Floor of the vehicle's CURRENT level (negative => basement; correct
      // for underground). 2.44949 is PZ's own level->physics-Y height.
      int level = PZMath.fastfloor(this.cc.vehicleObject.getZ());
      float floorY = level * 2.44949F;
      float physicsY = this.cc.vehicleObject.jniTransform.origin.y;

      boolean sunk = physicsY < floorY - sinkDepth;
      if (!sunk) {
         this.bvdSinkTicks = 0;
         return;
      }

      if (this.bvdGuardCooldown > 0) {
         this.bvdSinkTicks = 0;   // don't accrue dwell while cooling down
         return;
      }
      this.bvdSinkTicks++;
      if (this.bvdSinkTicks < dwellTicks) {
         return;
      }

      // Re-seat just above this level's floor (inside vanilla's legitimate
      // [level*2.44949, (level+0.995)*2.44949] band), then let vanilla's
      // own teleport push it to Bullet (which resets velocity).
      this.cc.vehicleObject.jniTransform.origin.y = floorY + 0.10F;
      this.cc.vehicleObject.setWorldTransform(this.cc.vehicleObject.jniTransform);
      this.bvdSinkTicks = 0;
      this.bvdGuardCooldown = cooldownTicks;
   }

   private void publishComputedState() {
      IsoPlayer local = IsoPlayer.getInstance();
      if (local == null || local.getVehicle() != this.cc.vehicleObject) {
         return;
      }
      KahluaTableImpl bridge = this.bvdBridge();
      if (bridge == null) {
         return;
      }
      if (this.computedOut == null) {
         this.computedOut = new KahluaTableImpl(new java.util.LinkedHashMap<>());
      }
      this.computedOut.rawset("tireFamily", this.tireFamilyOut);
      this.computedOut.rawset("gripRoad", (double)this.gripRoadOut);
      this.computedOut.rawset("gripWet", (double)this.gripWetOut);
      this.computedOut.rawset("gripSnow", (double)this.gripSnowOut);
      this.computedOut.rawset("gripOffroad", (double)this.gripOffroadOut);
      this.computedOut.rawset("ladenRatio", (double)this.ladenRatioOut);
      this.computedOut.rawset("loadPenalty", (double)this.loadPenaltyOut);
      bridge.rawset("computed", this.computedOut);
   }

