   // Populate the static reference maps once. Per-vehicle data comes from
   // BVD's own bridge table (BetterVehicleDynamicsMod). BVD applies its
   // HP/Weight values Lua-side, so for every vanilla vehicle these maps stay
   // empty and the in-Java drivetrain defaults are used — that absent-data
   // path is the parity behaviour. Drivetrain-part tags are resolved from the
   // optional companion part mod and are simply null when it is absent.
   private void loadLUATables() {
      KahluaTableImpl bridge = this.bvdBridge();

      // Decide whether a (re)build is needed. Two independent gates so the
      // stock / no-bridge path stays byte-identical to the old single-shot
      // boolean latch while the bridge-present path rebuilds once per world
      // load via the Lua-driven generation token.
      int bridgeSpecGen = -1;
      boolean haveGen = false;
      if (bridge != null) {
         bridgeSpecGen = bridge.rawgetInt("specGen");
         // rawgetInt yields -1 when the key is absent or non-numeric; a real
         // world-load generation is always >= 1, so treat -1 as "no token".
         haveGen = bridgeSpecGen >= 0;
      }

      if (haveGen) {
         if (bridgeSpecGen == loadedSpecGen) {
            return;
         }
      } else if (defaultsLoaded) {
         return;
      }

      tagBrakeBooster = ItemTag.get(ResourceLocation.of("ProjectSummerCar:EngineBrakeBooster"));
      tagPowerSteering = ItemTag.get(ResourceLocation.of("ProjectSummerCar:EnginePowerSteeringPump"));
      tagFanBelt = ItemTag.get(ResourceLocation.of("ProjectSummerCar:EngineFanBelt"));
      tagGearbox = ItemTag.get(ResourceLocation.of("ProjectSummerCar:EngineTransmission"));
      tagConverter = ItemTag.get(ResourceLocation.of("ProjectSummerCar:EngineTorqueConverter"));
      tagFlywheel = ItemTag.get(ResourceLocation.of("ProjectSummerCar:EngineFlywheel"));

      baseWheelFriction.clear();
      ArrayList allScripts = ScriptManager.instance.getAllVehicleScripts();
      for (int i = 0; i < allScripts.size(); i++) {
         VehicleScript vs = (VehicleScript)allScripts.get(i);
         baseWheelFriction.put(vs.getName(), vs.getWheelFriction());
      }

      vehicleSpecs.clear();
      engineSpecs.clear();
      gearboxSpecs.clear();
      converterSpecs.clear();

      if (bridge == null) {
         // Stock / no-bridge path: empty maps, in-Java drivetrain defaults.
         // Byte-identical to the previous single-shot boolean latch — it just
         // must not redo this work every tick. (loadedSpecGen is untouched so
         // it stays -1; if the bridge later appears, that path will rebuild.)
         defaultsLoaded = true;
         return;
      }

      // Per-vehicle reference values are exposed by the BVD Lua side under
      // the bridge's "vehicleData" channel ({fullType -> {hp,mass_kg,cargo}}).
      // Absent on stock BVD (HP/Weight is Lua-driven) -> empty map, defaults.
      Object vehData = bridge.rawget("vehicleData");
      if (vehData instanceof KahluaTableImpl) {
         KahluaTableImpl tbl = (KahluaTableImpl)vehData;
         for (Entry e : tbl.delegate.entrySet()) {
            String fullType = e.getKey().toString();
            BvdCar.VehicleSpec spec = new BvdCar.VehicleSpec();
            Object v = e.getValue();
            if (v instanceof KahluaTableImpl) {
               KahluaTableImpl row = (KahluaTableImpl)v;
               for (Entry f : row.delegate.entrySet()) {
                  String prop = f.getKey().toString();
                  if (prop.equals("engineSound")) {
                     spec.engineSound = f.getValue().toString();
                  } else if (prop.equals("cargo")) {
                     // Typed probe: a non-Double cargo value (Integer/String/
                     // nil from a future BVD pack) must not throw out of
                     // loadLUATables (runs per-tick + from the ctor). Leave
                     // the VehicleSpec default cargo when malformed.
                     if (f.getValue() instanceof Double dv) {
                        spec.cargo = (float)dv.doubleValue();
                     }
                  } else if (prop.equals("hp")) {
                     spec.realismApplied = true;
                  }
               }
            }
            vehicleSpecs.put(fullType, spec);
         }
      }

      // Optional engine-sound / gearbox / converter packs, also via the
      // bridge. Stock BVD ships none, so these stay empty.
      this.absorbEngineTable(bridge.rawget("engineData"));
      this.absorbGearboxTable(bridge.rawget("gearboxData"));
      this.absorbConverterTable(bridge.rawget("converterData"));

      // I2: latch / advance the generation only after a full successful parse
      // pass, so a (defensively guarded) malformed channel can retry on the
      // next call rather than latch a half-built state.
      if (haveGen) {
         loadedSpecGen = bridgeSpecGen;
      } else {
         // Bridge present but no specGen token (older/partial Lua): preserve
         // load-once semantics via the same latch the no-bridge path uses.
         defaultsLoaded = true;
      }
   }

   private void absorbEngineTable(Object data) {
      if (!(data instanceof KahluaTableImpl)) {
         return;
      }
      for (Entry e : ((KahluaTableImpl)data).delegate.entrySet()) {
         String id = e.getKey().toString();
         BvdCar.EngineSpec es = new BvdCar.EngineSpec();
         Object v = e.getValue();
         if (v instanceof KahluaTableImpl) {
            for (Entry f : ((KahluaTableImpl)v).delegate.entrySet()) {
               String prop = f.getKey().toString();
               Object val = f.getValue();
               if (prop.equals("engineSound")) {
                  es.engineSound = val.toString();
               } else if (prop.equals("engineSoundRPM")) {
                  if (val instanceof Double dv) { es.engineSoundRpm = (float)dv.doubleValue(); }
               } else if (prop.equals("exhaustSound")) {
                  es.exhaustSound = val.toString();
               } else if (prop.equals("crankSound")) {
                  es.crankSound = val.toString();
               } else if (prop.equals("startSound")) {
                  es.startSound = val.toString();
               }
            }
         }
         engineSpecs.put(id, es);
      }
   }

   private void absorbGearboxTable(Object data) {
      if (!(data instanceof KahluaTableImpl)) {
         return;
      }
      for (Entry e : ((KahluaTableImpl)data).delegate.entrySet()) {
         BvdCar.GearboxSpec gs = new BvdCar.GearboxSpec();
         String name = "";
         ArrayList<Float> ratioList = new ArrayList<>();
         Object v = e.getValue();
         if (v instanceof KahluaTableImpl) {
            for (Entry f : ((KahluaTableImpl)v).delegate.entrySet()) {
               String prop = f.getKey().toString();
               if (prop.equals("name")) {
                  name = f.getValue().toString();
               } else if (prop.equals("ratios") && f.getValue() instanceof KahluaTableImpl) {
                  for (Entry r : ((KahluaTableImpl)f.getValue()).delegate.entrySet()) {
                     if (r.getValue() instanceof Double rv) {
                        ratioList.add((float)rv.doubleValue());
                     }
                  }
               }
            }
         }
         // Guard the empty/garbled ratio list: never set gearCount to -1
         // (every later gear index would fault). Skip the spec entry so the
         // in-Java default gearbox for that vehicle is used instead.
         if (ratioList.isEmpty()) {
            continue;
         }
         gs.ratios = new float[ratioList.size()];
         for (int i = 0; i < ratioList.size(); i++) {
            gs.ratios[i] = ratioList.get(i);
         }
         gs.gearCount = ratioList.size() - 1;
         gearboxSpecs.put(name, gs);
      }
   }

   private void absorbConverterTable(Object data) {
      if (!(data instanceof KahluaTableImpl)) {
         return;
      }
      for (Entry e : ((KahluaTableImpl)data).delegate.entrySet()) {
         BvdCar.ConverterSpec cs = new BvdCar.ConverterSpec();
         String name = "";
         Object v = e.getValue();
         if (v instanceof KahluaTableImpl) {
            for (Entry f : ((KahluaTableImpl)v).delegate.entrySet()) {
               String prop = f.getKey().toString();
               if (prop.equals("name")) {
                  name = f.getValue().toString();
               } else if (prop.equals("lockupRPM")) {
                  if (f.getValue() instanceof Double dv) { cs.lockupRpm = (float)dv.doubleValue(); }
               } else if (prop.equals("lockupRange")) {
                  if (f.getValue() instanceof Double dv) { cs.lockupRange = (float)dv.doubleValue(); }
               }
            }
         }
         converterSpecs.put(name, cs);
      }
   }

   // --- Bridge-driven option mirror ---------------------------------------

   private void updateModOptions() {
      if (--this.configRefreshCountdown > 0) {
         return;
      }
      this.configRefreshCountdown = 60;
      // Drop the resolved-sandbox-handle cache on the same ~60-tick cadence so
      // an option that registered after our first touch (or a miss-cached key)
      // is re-resolved. Behaviour-identical: every getSandboxOption* call still
      // reads the live value from its handle; this only periodically forgets
      // the handle so a fresh getOptionByName runs at most once per ~60 ticks
      // per key instead of every substep.
      this.sandboxHandleCache.clear();
      this.sandboxHandleMisses.clear();
      KahluaTableImpl bridge = this.bvdBridge();
      if (bridge == null) {
         return;
      }
      this.manualGearbox = bridge.rawgetBool("manualShift");
      this.autoReverseEnabled = bridge.rawgetBool("autoReverse") || !this.manualGearbox;
      this.analogPedals = bridge.rawgetBool("useAnalogThrottle") && this.cc.vehicleObject.getJoypad() != -1;
      this.joystickPedalAxis = bridge.rawgetBool("JoystickThrottle");
      this.tunableSteering = bridge.rawgetBool("CustomizableSteering");
      this.steerGainLow = bridge.rawgetFloat("SteeringFactorLowSpeed");
      this.steerGainHigh = bridge.rawgetFloat("SteeringFactorHighSpeed");
      this.steerReturnLow = bridge.rawgetFloat("SteeringCenteringLowSpeed");
      this.steerReturnHigh = bridge.rawgetFloat("SteeringCenteringHighSpeed");
      this.steerSnap = bridge.rawgetFloat("SteeringSnapback");
      this.steerHighSpeedRef = bridge.rawgetFloat("SteeringHighSpeed");
   }

   // --- Input + pedal resolution ------------------------------------------

   // Resolve forward/reverse/brake intent from the (digital or analog) pedals,
   // handle the drunk-driver command lag, the regulator, throttle smoothing,
   // brake-booster scaling and the brake lights. Mirrors the predecessor's
   // input pipeline behaviour exactly while leaving force application to the
   // physics model in update().
   private void updateControlsCalculation(ItemContainer engineBox) {
      this.cc.speed = this.cc.vehicleObject.getCurrentSpeedKmHour();
      boolean drunk = this.cc.vehicleObject.getDriver() != null
         && this.cc.vehicleObject.getDriver().getMoodles().getMoodleLevel(MoodleType.DRUNK) > 1;

      float forwardDot = 0.0F;
      Vector3f vel = this.cc.vehicleObject.getLinearVelocity(this.tempVec3f2);
      vel.y = 0.0F;
      if (vel.length() > 0.5) {
         vel.normalize();
         Vector3f facing = this.tempVec3f;
         this.cc.vehicleObject.getForwardVector(facing);
         forwardDot = vel.dot(facing);
      }

      float dt = GameTime.getInstance().getRealworldSecondsSinceLastUpdate();
      float fakeSpeed = this.cc.vehicleObject.getCurrentSpeedKmHour() * BaseVehicle.getFakeSpeedModifier();
      this.isGas = false;
      this.isGasR = false;
      this.isBreak = false;

      boolean autoRev = this.autoReverseEnabled;
      if (this.cc.clientControls.shift) {
         autoRev = false;
      }

      if (autoRev && this.analogPedals) {
         if (forwardDot >= 0.0F && this.pedalGas - this.pedalBrake > 0.0F) {
            this.isGas = true;
            this.reversing = false;
         }

         if (forwardDot <= 0.0F && this.pedalGas - this.pedalBrake < 0.0F) {
            this.isGasR = true;
            this.reversing = true;
         }

         if (this.reversing) {
            float swap = this.pedalGas;
            this.pedalGas = this.pedalBrake;
            this.pedalBrake = swap;
         }
      }

      if (autoRev && !this.analogPedals) {
         if (this.cc.clientControls.backward) {
            if (forwardDot > 0.0F) {
               this.isBreak = true;
            }

            if (forwardDot <= 0.0F) {
               this.isGasR = true;
               this.reversing = true;
            }
         }

         if (this.cc.clientControls.forward) {
            if (forwardDot < 0.0F) {
               this.isBreak = true;
            }

            if (forwardDot >= 0.0F) {
               this.isGas = true;
               this.reversing = false;
            }

            if (this.isGasR) {
               this.isGasR = false;
               this.isBreak = true;
            }
         }
      } else if (!autoRev && !this.analogPedals) {
         this.reversing = false;
         if (this.cc.clientControls.forward) {
            this.isGas = true;
         }

         if (this.cc.clientControls.backward) {
            this.isBreak = true;
         }
      }

      if (this.cc.clientControls.brake) {
         this.isBreak = true;
      }

      if (drunk && this.cc.vehicleObject.getEngineState() != engineStateTypes.Idle) {
         if (this.isBreak && !this.wasBreaking) {
            this.isBreak = this.delayCommandWhileDrunk(this.isBreak);
         }

         if (this.isGas && !this.wasGas) {
            this.isGas = this.delayCommandWhileDrunk(this.isGas);
         }

         if (this.isGasR && !this.wasGasR) {
            this.isGasR = this.delayCommandWhileDrunk(this.isGas);
         }

         if (this.cc.clientControls.steering != 0.0F && !this.wasSteering) {
            this.cc.clientControls.steering = this.delayCommandWhileDrunk(this.cc.clientControls.steering);
         }
      }

      this.updateRegulator(dt);
      this.wasBreaking = this.isBreak;
      this.wasGas = this.isGas;
      this.wasGasR = this.isGasR;
      this.wasSteering = this.cc.clientControls.steering != 0.0F;
      if (!this.isGasR && this.cc.vehicleObject.isInvalidChunkAhead()) {
         this.isBreak = true;
         this.isGas = false;
         this.isGasR = false;
      } else if (!this.isGas && this.cc.vehicleObject.isInvalidChunkBehind()) {
         this.isBreak = true;
         this.isGas = false;
         this.isGasR = false;
      }

      if (this.cc.clientControls.shift) {
         this.isGas = false;
         this.isGasR = false;
         this.cc.clientControls.wasUsingParkingBrakes = false;
         this.reversing = false;
      }

      float throttle = this.cc.vehicleObject.throttle;
      if (this.cc.vehicleObject.isRegulator() && !this.isGas && !this.isGasR) {
         float gap = this.cc.vehicleObject.getRegulatorSpeed() - fakeSpeed;
         throttle = Math.min(Math.max(gap * 0.5F, 0.0F), 1.0F);
         if (this.isBreak) {
            throttle = 0.0F;
         }
      }

      IsoGameCharacter driver = this.cc.vehicleObject.getDriver();
      boolean fastDriver = driver != null && driver.hasTrait(CharacterTrait.SPEED_DEMON);
      boolean slowDriver = driver != null && driver.hasTrait(CharacterTrait.SUNDAY_DRIVER);
      if (this.analogPedals) {
         if (!this.cc.vehicleObject.isRegulator()) {
            throttle = this.pedalGas;
            this.overrev = this.pedalGas > 0.9 ? 1.0F : 0.0F;
         } else {
            this.overrev = 0.0F;
         }
      } else {
         if (!this.isGas && !this.isGasR) {
            if (slowDriver) {
               throttle -= dt * 6.0F;
            } else if (fastDriver) {
               throttle -= dt * 2.0F;
            } else {
               throttle -= dt * 4.0F;
            }
         } else if (slowDriver) {
            throttle += dt * 2.0F;
         } else if (fastDriver) {
            throttle += dt * 6.0F;
         } else {
            throttle += dt * 4.0F;
         }

         if (throttle >= 1.0F) {
            if (slowDriver) {
               this.overrev += dt * 0.3F;
            } else {
               this.overrev += dt * 1.0F;
            }
         } else {
            this.overrev -= dt * 1.0F;
         }
      }

      this.overrev = PZMath.clamp(this.overrev, 0.0F, 1.0F);
      throttle = PZMath.clamp(throttle, 0.0F, 1.0F);
      this.cc.engineForce = 0.0F;
      this.cc.brakingForce = 0.0F;
      if (GameClient.client) {
         throttle = Math.min(throttle, (float)(ServerOptions.instance.speedLimit.getValue() - this.cc.vehicleObject.getCurrentSpeedKmHour() - 2.0) / 2.0F);
      }

      this.cc.vehicleObject.throttle = throttle;
      if (this.isGas || this.isGasR || this.isBreak) {
         UIManager.speedControls.SetCurrentGameSpeed(1);
      }

      if ((this.isGasR || this.isGas) && this.cc.clientControls.wasUsingParkingBrakes) {
         this.cc.clientControls.wasUsingParkingBrakes = false;
      }

      this.updateBackSignal();
      if (this.analogPedals) {
         this.isBreak = this.isBreak | this.pedalBrake > 0.1;
      }

      if (this.isBreak) {
         this.cc.brakingForce = this.cc.vehicleObject.getBrakingForce();
         if (this.analogPedals && !this.cc.clientControls.brake) {
            this.cc.brakingForce *= this.pedalBrake;
         }

         if (this.cc.clientControls.brake) {
            this.cc.brakingForce *= 3.0F;
         }

         if (engineBox != null) {
            InventoryItem booster = engineBox.getFirstTag(tagBrakeBooster);
            float boost = 0.0F;
            if (booster != null) {
               boost = Math.min(1.0F, booster.getCondition() / 50.0F);
            }

            if (!this.cc.vehicleObject.isEngineRunning()) {
               boost = 0.0F;
            }

            this.cc.brakingForce = (float)(this.cc.brakingForce * Math.max(0.2, (double)boost));
         }
      }

      this.updateBrakeLights();
      BaseVehicle towedBy = this.cc.vehicleObject.getVehicleTowedBy();
      if (towedBy != null && towedBy.getDriver() == null && this.cc.vehicleObject.getDriver() != null && !GameClient.client) {
         this.cc.vehicleObject.addPointConstraint(null, towedBy, this.cc.vehicleObject.getTowAttachmentSelf(), towedBy.getTowAttachmentSelf());
      }
   }

   // --- Steering -----------------------------------------------------------

   // When the player is holding the drift key the steering rack turns the
   // front wheels in faster than usual, so the car can rotate into a corner
   // while the rear is loose. Returns a multiplier (1.0 = no drift assist).
   private float getDriftSteeringBoost() {
      if (!this.getSandboxOptionBoolean("BetterVehicleDynamics.Drift", false)) {
         return 1.0F;
      }
      KahluaTableImpl bridge = this.bvdBridge();
      if (bridge != null && bridge.rawgetBool("driftActive")) {
         return this.getSandboxOption("BetterVehicleDynamics.DriftSteer", 1.5F);
      }
      return 1.0F;
   }

   // Stock-feel steering: turn-in scaled by remaining speed headroom, then a
   // soft self-centre when the wheel is released. Used when tunable steering
   // is disabled on the bridge.
   private void updateSteeringStock(VehicleScript script) {
      float fps = GameTime.getInstance().getMultiplier() / 0.8F;
      float driftBoost = this.getDriftSteeringBoost();
      if (Math.abs(this.cc.clientControls.steering) > 0.1F) {
         float headroom = 1.0F - this.cc.speed / this.cc.vehicleObject.getMaxSpeed();
         if (headroom < 0.1F) {
            headroom = 0.1F;
         }

         this.steerAngle = this.steerAngle - (this.cc.clientControls.steering + this.steerAngle) * 0.06F * fps * headroom * driftBoost;
      } else if (Math.abs(this.steerAngle) <= 0.04) {
         this.steerAngle = 0.0F;
      } else if (this.steerAngle > 0.0F) {
         this.steerAngle -= 0.04F * fps;
         this.steerAngle = Math.max(this.steerAngle, 0.0F);
      } else {
         this.steerAngle += 0.04F * fps;
         this.steerAngle = Math.min(this.steerAngle, 0.0F);
      }

      float clamp = script.getSteeringClamp(this.cc.speed);
      this.steerAngle = PZMath.clamp(this.steerAngle, -clamp, clamp);
   }

   // Tunable steering: low/high-speed turn-in and self-centre rates blend
   // linearly with speed up to a reference speed; an optional power-steering
   // part softens response as engine RPM and pump condition fall; a snapback
   // multiplier sharpens turn-in when steering further into the current lean.
   private void updateSteeringTunable(ItemContainer engineBox, VehicleScript script, float dt) {
      float blend = Math.min(1.0F, Math.abs(this.cc.speed) / this.steerHighSpeedRef);
      float turnIn = this.steerGainLow + (this.steerGainHigh - this.steerGainLow) * blend;
      float selfCentre = this.steerReturnLow + (this.steerReturnHigh - this.steerReturnLow) * blend;

      if (engineBox != null) {
         InventoryItem pump = engineBox.getFirstTag(tagPowerSteering);
         InventoryItem belt = engineBox.getFirstTag(tagFanBelt);
         float pumpHealth = 0.0F;
         float beltHealth = 0.0F;
         if (pump != null) {
            pumpHealth = pump.getCondition();
            pumpHealth *= Math.min(1.0F, pump.getFluidContainer().getFilledRatio() * 2.0F);
         }

         if (belt != null) {
            beltHealth = belt.getCondition();
         }

         float assist = pumpHealth / 50.0F * Math.max(1.0F, beltHealth / 30.0F) * (float)this.cc.vehicleObject.getEngineSpeed() / 2000.0F;
         turnIn = Math.min(turnIn, assist * this.steerGainLow);
      }

      boolean activelyTurning = false;
      if (Math.abs(this.cc.clientControls.steering) > 0.1F) {
         if (this.cc.clientControls.steering < 0.0F == this.steerAngle < 0.0F) {
            turnIn *= this.steerSnap;
         }

         this.steerAngle = this.steerAngle - (this.cc.clientControls.steering + this.steerAngle) * 3.0F * dt * turnIn * this.getDriftSteeringBoost();
         activelyTurning = true;
      } else if (Math.abs(this.steerAngle) <= 0.04) {
         this.steerAngle = 0.0F;
      }

      if (!activelyTurning) {
         if (this.steerAngle > 0.0F) {
            this.steerAngle -= selfCentre * 4.0F * dt;
            this.steerAngle = Math.max(this.steerAngle, 0.0F);
         } else {
            this.steerAngle += selfCentre * 4.0F * dt;
            this.steerAngle = Math.min(this.steerAngle, 0.0F);
         }
      }

      float clamp = script.getSteeringClamp(this.cc.speed);
      this.steerAngle = PZMath.clamp(this.steerAngle, -clamp, clamp);
   }

   // --- Grip + drag --------------------------------------------------------

   // Aggregate tire pressure/condition and fold in the sandbox grip budget
   // plus weather/surface penalties. Result is a 0..~1 grip scalar.
   private void updateTireStats() {
      VehicleScript script = this.cc.vehicleObject.getScript();
      int wheelCount = script.getWheelCount();
      float fillSum = 0.0F;
      float wearSum = 0.0F;

      // Optional per-tire-family character profile, published by the Lua side
      // under bridge["tireProfiles"][family] = {road,wet,snow,offroad}. When
      // nothing publishes it (the only state today) tp is null and the loop
      // below leaves every per-surface average at exactly 1.0F, so the gated
      // multiplies further down are skipped entirely and the grip arithmetic
      // is byte-identical to before this contract existed.
      KahluaTableImpl tp = null;
      KahluaTableImpl bridge = this.bvdBridge();
      if (bridge != null) {
         Object rawTp = bridge.rawget("tireProfiles");
         if (rawTp instanceof KahluaTableImpl) {
            tp = (KahluaTableImpl)rawTp;
         }
      }

      float profRoadSum = 0.0F;
      float profWetSum = 0.0F;
      float profSnowSum = 0.0F;
      float profOffroadSum = 0.0F;
      String firstFamily = "";

      for (int i = 0; i < wheelCount; i++) {
         Wheel wheel = script.getWheel(i);
         String familyKey = "";
         if (wheel != null) {
            VehiclePart part = this.cc.vehicleObject.getPartById("Tire" + wheel.getId());
            if (part != null && part.getInventoryItem() != null) {
               fillSum += part.getContainerContentAmount() / part.getContainerCapacity();
               wearSum += part.getCondition() * part.getInventoryItem().getWheelFriction();
               this.cc.vehicleObject.setTireInflation(i, 1.0F);
               familyKey = this.tireFamilyKeyCached(part.getInventoryItem().getType());
               if (firstFamily.isEmpty()) {
                  firstFamily = familyKey;
               }
            }
         }

         // A wheel with no tire (or no profile row for its family) contributes
         // the neutral 1.0 for every surface, so the average is never skewed.
         KahluaTableImpl row = null;
         if (tp != null && !familyKey.isEmpty()) {
            Object rawRow = tp.rawget(familyKey);
            if (rawRow instanceof KahluaTableImpl) {
               row = (KahluaTableImpl)rawRow;
            }
         }

         // Identity path (no policy published) does zero extra float work:
         // the sums stay 0 and the per-surface averages keep their 1.0F
         // defaults below, which is byte-identical to accumulating 1.0F per
         // wheel and dividing by wheelCount. When tp != null the sums are
         // accumulated exactly as before, so the result is unchanged.
         if (tp != null) {
            profRoadSum += bridgeFieldOr(row, "road", 1.0F);
            profWetSum += bridgeFieldOr(row, "wet", 1.0F);
            profSnowSum += bridgeFieldOr(row, "snow", 1.0F);
            profOffroadSum += bridgeFieldOr(row, "offroad", 1.0F);
         }
      }

      float profRoad = 1.0F;
      float profWet = 1.0F;
      float profSnow = 1.0F;
      float profOffroad = 1.0F;
      if (wheelCount > 0) {
         fillSum /= wheelCount;
         wearSum = wearSum * 0.01F / wheelCount;
         if (tp != null) {
            profRoad = profRoadSum / wheelCount;
            profWet = profWetSum / wheelCount;
            profSnow = profSnowSum / wheelCount;
            profOffroad = profOffroadSum / wheelCount;
         }
      }

      this.tireFill = fillSum;
      this.tireWear = wearSum;
      float grip = this.tireWear * 0.5F + 0.5F;
      grip *= this.getSandboxOption("BetterVehicleDynamics.GripLevel", 1.0F);
      // Profile is a CHARACTER multiplier on top of vanilla wheelFriction
      // (which still sets the magnitude) -- gated so the no-policy path runs
      // the original arithmetic unchanged.
      if (tp != null) {
         grip *= profRoad;
      }

      float snowGrip = 1.0F;
      if (ClimateManager.getInstance().getSnowStrength() > 0.5F) {
         float snowLoss = 1.0F - this.getSandboxOption("BetterVehicleDynamics.SnowGrip", 0.45F);
         snowLoss = (float)(snowLoss * (Math.min(Math.max(ClimateManager.getInstance().getSnowStrength(), 0.0F), 5.0F) * 0.2));
         snowGrip = (1.0F - snowLoss) * (OFFROAD_GRIP_LOW + (OFFROAD_GRIP_HIGH - OFFROAD_GRIP_LOW) * this.offroadAptitude(script));
         if (tp != null) {
            snowGrip *= profSnow;
         }
      }

      float surfaceGrip = 1.0F;
      if (this.cc.vehicleObject.isDoingOffroad()) {
         float offLoss = this.getSandboxOption("BetterVehicleDynamics.OffroadGrip", 0.85F);
         offLoss = 1.0F - offLoss;
         offLoss *= 0.5F + this.tireFill / 2.0F;
         surfaceGrip = (1.0F - offLoss) * (OFFROAD_GRIP_LOW + (OFFROAD_GRIP_HIGH - OFFROAD_GRIP_LOW) * this.offroadAptitude(script));
         if (tp != null) {
            surfaceGrip *= profOffroad;
         }
         // v0.1.8 (42.19 bundle): belt-and-braces clamp. The arithmetic above
         // can produce <= 0 if sandbox, tireFill, or a published tireProfile
         // off-road row pushes the result negative; negative surfaceGrip would
         // feed an inverted gripLimit downstream (engine pulling backwards).
         if (surfaceGrip < 0.05F) {
            surfaceGrip = 0.05F;
         }
      }

      if (ClimateManager.getInstance().isRaining()) {
         surfaceGrip *= this.getSandboxOption("BetterVehicleDynamics.WetGrip", 0.7F);
         if (tp != null) {
            surfaceGrip *= profWet;
         }
      }

      // Surface-neutral base grip: GripLevel + wear (+ profRoad when a
      // profile is published), but BEFORE any wet/snow/offroad fold. This is
      // exactly the grip a car has on plain dry road. Captured here so the
      // per-surface readout can re-derive each surface's effective grip
      // without double-counting the fold that grip is about to absorb.
      float gripBase = grip;
      grip *= Math.min(1.0F, Math.min(snowGrip, surfaceGrip));
      this.gripFactor = grip;

      // Reporting-only per-surface readout (Step 5). Contract: each *Out is
      // the EFFECTIVE grip the car actually has on that surface in the
      // current conditions -- i.e. what this.gripFactor would equal if only
      // that surface were active -- with every profile/sandbox factor
      // applied exactly once. snowGrip already folds in profSnow, SnowGrip
      // and offroadEfficiency; surfaceGrip already folds in profOffroad,
      // OffroadGrip (and, when raining, WetGrip*profWet). Nothing here feeds
      // back into the physics.
      this.tireFamilyOut = firstFamily;
      this.gripRoadOut = gripBase;
      this.gripWetOut = ClimateManager.getInstance().isRaining()
         ? gripBase * this.getSandboxOption("BetterVehicleDynamics.WetGrip", 0.7F) * (tp != null ? profWet : 1.0F)
         : gripBase;
      this.gripSnowOut = (ClimateManager.getInstance().getSnowStrength() > 0.5F)
         ? gripBase * Math.min(1.0F, snowGrip)
         : gripBase;
      this.gripOffroadOut = this.cc.vehicleObject.isDoingOffroad()
         ? gripBase * Math.min(1.0F, surfaceGrip)
         : gripBase;
   }

   // Push the script's effective wheel friction toward the grip target, and
   // apply aerodynamic + rolling drag as a central force. While drifting,
   // friction is slashed and a yaw torque is applied so the car rotates into
   // the corner (PZ exposes no per-wheel friction, so this is the arcade
   // equivalent of a handbrake-pull rotation).
   private void applyFriction() {
      VehicleScript script = this.cc.vehicleObject.getScript();
      Float baseFric = baseWheelFriction.get(script.getName());
      if (baseFric == null) {
         DebugLog.log("[BetterVehicleDynamics] no recorded base wheel friction for " + script.getName());
         return;
      }

      float target = baseFric * this.gripFactor;
      target = Math.min(1.8F, target);

      if (this.getSandboxOptionBoolean("BetterVehicleDynamics.Drift", false)) {
         KahluaTableImpl bridge = this.bvdBridge();
         if (bridge != null && bridge.rawgetBool("driftActive")) {
            float minSpeed = this.getSandboxOption("BetterVehicleDynamics.DriftMinSpeed", 20.0F);
            float gripMult = this.getSandboxOption("BetterVehicleDynamics.DriftGrip", 0.35F);
            float absSpeed = Math.abs(this.cc.vehicleObject.getCurrentSpeedKmHour());
            if (absSpeed > minSpeed && Math.abs(this.cc.clientControls.steering) > 0.25F) {
               target *= gripMult;

               float rotScale = this.getSandboxOption("BetterVehicleDynamics.DriftRotation", 2000.0F);
               // Steering convention: negative = left, positive = right. In
               // Bullet's Y-up frame a positive yaw rotates counter-clockwise
               // seen from above, so torque = -steering * scale. Heavier
               // vehicles need proportionally more torque, hence the mass term.
               float yaw = -this.cc.clientControls.steering * rotScale * (this.cc.vehicleObject.getMass() * 0.001F);
               Bullet.applyTorqueToVehicle(this.cc.vehicleObject.vehicleId, 0.0F, yaw, 0.0F);
            }
         }
      }

      // Grip-model gate is always-on per the BVD sandbox taxonomy: there is no
      // "GripLevelEnabled" tickbox to disable it (grip is tuned by the GripLevel
      // / SnowGrip / WetGrip / OffroadGrip knobs instead). The undeclared key
      // resolves to its true fallback every call, so this is held as a constant
      // to make the always-on intent explicit and skip the per-substep lookup.
      boolean applyGrip = true;
      if (this.cc.vehicleObject.getDriver() != null) {
         lastDrivenScript = script.getName();
      } else if (lastDrivenScript.equals(script.getName())) {
         applyGrip = false;
      }

      if (applyGrip) {
         Float lastApplied = lastAppliedFriction.get(script.getName());
         if (lastApplied != null && Math.abs(lastApplied - target) < FRICTION_EPSILON) {
            // The shared script's wheelFriction is already at this target
            // (within a sub-physical epsilon); the Load + toBullet round-trip
            // would reproduce the identical effective friction. Skip it.
            return;
         }
         try {
            script.Load(script.getName(), "{ wheelFriction = " + target + ", }");
            script.toBullet();
            lastAppliedFriction.put(script.getName(), target);
         } catch (Exception ex) {
            DebugLog.log("[BetterVehicleDynamics] failed to push wheelFriction to script");
         }
      }
   }

   private void applyDrag(float dt) {
      VehicleScript script = this.cc.vehicleObject.getScript();
      this.applyFriction();
      float absSpeed = Math.abs(this.cc.vehicleObject.getCurrentSpeedKmHour() * BaseVehicle.getFakeSpeedModifier());
      float drag = absSpeed * absSpeed * 0.05F;
      drag *= this.getSandboxOption("BetterVehicleDynamics.Drag", 1.0F);
      if (script.getMechanicType() == 3) {
         drag *= 0.7F;
      } else if (script.getMechanicType() == 2) {
         drag *= 1.5F;
      }

      if (this.cc.vehicleObject.isDoingOffroad()) {
         float dragShape = OFFROAD_DRAG_LOW + (OFFROAD_DRAG_HIGH - OFFROAD_DRAG_LOW) * this.offroadAptitude(script);

         float roll = this.getSandboxOption("BetterVehicleDynamics.RollResistanceOffroad", 1.8F) * 0.2F;
         // v0.1.8 (42.19 bundle): speed-dependent off-road drag halved.
         // 0.01F made cars feel quagmire-slow above ~40 km/h even with grip
         // floors maxed; the base term + mass + 1/eff still encode "off-road
         // resists motion" so this just tames the per-km/h compounding.
         roll += 0.005F * absSpeed;
         roll *= this.cc.vehicleObject.getMass() * (1.0F + this.tireFill * 0.6F) / dragShape;
         // never more than a share of the traction the tires can give
         if (this.lastGripLimit > 0.0F) {
            roll = Math.min(roll, OFFROAD_DRAG_BUDGET * this.lastGripLimit);
         }
         drag += roll;
      } else {
         float roll = this.getSandboxOption("BetterVehicleDynamics.RollResistance", 1.0F) * 0.05F;
         roll += 0.001F * absSpeed;
         roll *= this.cc.vehicleObject.getMass() * (2.0F - this.tireFill);
         drag += roll;
      }

      Vector3f dir = this.dragDir.set(this.cc.vehicleObject.jniLinearVelocity);
      if (dir.lengthSquared() > 0.1) {
         dir.normalize();
      }

      dir.mul(drag * BvdWorld.massScaler * dt * -200.0F);
      Bullet.applyCentralForceToVehicle(this.cc.vehicleObject.vehicleId, dir.x, dir.y, dir.z);
   }

   // --- Idle + audio -------------------------------------------------------

   private void updateIdle(float dt, VehiclePart enginePart) {
      this.idleRpmRetimer -= dt;
      if (this.idleRpmRetimer <= 0.0F) {
         this.idleRpmRetimer = 0.1F;
         if (enginePart != null) {
            this.idleRpmTarget = Rand.Next(650, 700 + (200 - enginePart.getCondition() * 2));
         }
      }

      float rpm = (float)this.cc.vehicleObject.getEngineSpeed();
      if (rpm < this.idleRpmTarget) {
         float bump = Math.min(Math.max((this.idleRpmTarget - rpm) * 0.01F, 0.0F), 0.3F);
         this.cc.vehicleObject.throttle = Math.max(bump, this.cc.vehicleObject.throttle);
      }
   }

   // Engine-sound overhaul. Entirely data-gated: with no engine-sound spec
   // (the stock BVD case) this is a no-op and PZ's own engine audio plays.
   private void updateAudio(float dt, BvdCar.VehicleSpec spec) {
      if (GameServer.server) {
         return;
      }
      if (spec == null || spec.engineSound == null || spec.engineSound.isEmpty()) {
         return;
      }
      BvdCar.EngineSpec es = engineSpecs.get(spec.engineSound);
      if (es == null) {
         return;
      }

      BaseSoundEmitter local = this.cc.vehicleObject.getEmitter();
      if (this.cc.vehicleObject.getEngineState() == engineStateTypes.Starting && !local.isPlaying(this.crankSoundId)) {
         this.crankSoundId = local.playSoundImpl(es.crankSound, (IsoObject)null);
      }

      if (this.cc.vehicleObject.getEngineState() != engineStateTypes.Starting && local.isPlaying(this.crankSoundId)) {
         local.stopSound(this.crankSoundId);
      }

      if (this.cc.vehicleObject.getEngineState() == engineStateTypes.StartingSuccess && !local.isPlaying(this.startSoundId)) {
         this.startSoundId = local.playSoundImpl(es.startSound, (IsoObject)null);
         this.startupBlend = 0.0F;
      }

      float pitch = (float)this.cc.vehicleObject.getEngineSpeed() / es.engineSoundRpm;
      pitch = (pitch + 0.4F) / 1.4F;
      BaseSoundEmitter loop = this.loopEmitter;
      if (this.loopEngineId == 0L && this.cc.vehicleObject.isEngineRunning()) {
         if (loop != null) {
            loop.stopAll();
         }

         this.loopEmitter = IsoWorld.instance.getFreeEmitter(this.cc.vehicleObject.getX(), this.cc.vehicleObject.getY(), (int)this.cc.vehicleObject.getZ());
         loop = this.loopEmitter;
         this.loopEngineId = loop.playSoundImpl(es.engineSound, (IsoObject)null);
         if (!es.exhaustSound.isEmpty()) {
            this.loopExhaustId = loop.playSoundImpl(es.exhaustSound, (IsoObject)null);
         }
      }

      if (this.loopEngineId != 0L && !this.cc.vehicleObject.isEngineRunning() && loop != null) {
         loop.stopSound(this.loopEngineId);
         this.loopEngineId = 0L;
         loop.stopSound(this.loopExhaustId);
         this.loopExhaustId = 0L;
      }

      float vol = Core.getInstance().getOptionVehicleEngineVolume() / 10.0F;
      if (this.cc.vehicleObject.isEngineRunning()) {
         this.startupBlend = Math.min(1.0F, this.startupBlend + dt * 1.0F);
      }

      KahluaTableImpl bridge = this.bvdBridge();
      float overhaulVol = 0.4F;
      if (bridge != null) {
         overhaulVol = bridge.rawgetFloat("EngineOverhaulVolume");
      }

      if (this.startSoundId != 0L && local.isPlaying(this.startSoundId)) {
         local.setVolume(this.startSoundId, (1.0F - this.startupBlend) * vol * overhaulVol);
      }

      if (this.crankSoundId != 0L && local.isPlaying(this.crankSoundId)) {
         local.setVolume(this.crankSoundId, vol * overhaulVol);
      }

      if (this.loopEngineId != 0L) {
         this.loopEmitter.setPos(this.cc.vehicleObject.getX(), this.cc.vehicleObject.getY(), this.cc.vehicleObject.getZ());
         loop.setPitch(this.loopEngineId, pitch);
         loop.setPitch(this.loopExhaustId, pitch);
         loop.setVolume(this.loopEngineId, (this.cc.vehicleObject.throttle * 0.2F + 0.5F) * vol * this.startupBlend * overhaulVol);
         loop.setVolume(this.loopExhaustId, (this.cc.vehicleObject.throttle * 0.8F + 0.2F) * vol * this.startupBlend * overhaulVol);
      }
   }

   // --- Main physics tick --------------------------------------------------

   public void update() {
      // 42.20: vehicles can lack an engine entirely (burnt wrecks, trailers
      // on the vehicle path). Mirror vanilla: neutral box, no engine force,
      // a light parking brake, and skip the powertrain model.
      if (this.cc.vehicleObject.getEngine() == null) {
         this.cc.vehicleObject.transmissionNumber = TransmissionNumber.N;
         this.cc.engineForce = 0.0F;
         this.cc.brakingForce = 10.0F;
         if (!GameServer.server && this.cc.vehicleObject.getScript().getWheelCount() > 0) {
            Bullet.controlVehicle(this.cc.vehicleObject.vehicleId, 0.0F, this.cc.brakingForce, this.steerAngle);
         }
         return;
      }
      this.loadLUATables();
      this.updateModOptions();
      float dt = GameTime.getInstance().getRealworldSecondsSinceLastUpdate();
      BvdCar.VehicleSpec spec = vehicleSpecs.get(this.cc.vehicleObject.getScript().getFullType());
      this.updateAudio(dt, spec);
      if (this.cc.vehicleObject.getVehicleTowedBy() != null) {
         return;
      }

      VehiclePart enginePart = this.cc.vehicleObject.getPartById("Engine");
      ItemContainer engineBox = null;
      if (enginePart != null && partPackLoaded()) {
         engineBox = enginePart.getItemContainer();
      }

      KahluaTableImpl bridge = this.bvdBridge();
      VehicleScript script = this.cc.vehicleObject.getScript();
      this.updateControlsCalculation(engineBox);

      // Map the configured top speed onto an RPM band, then derive the gear
      // ratio set (3/4/5-speed defaults; bridge-supplied gearbox if present).
      float topSpeed = Math.min(120.0F, this.cc.vehicleObject.getMaxSpeed());
      float redline = 4500.0F;
      float shiftRpm = 4350.0F;
      if (script.getEngineRPMType().equals("firebird")) {
         redline = 6000.0F;
         shiftRpm = 5800.0F;
      }

      topSpeed /= redline;
      float speedToRpm = 0.95F / topSpeed;
      float wheelRpm = Math.abs(this.cc.vehicleObject.getCurrentSpeedKmHour() * BaseVehicle.getFakeSpeedModifier()) * speedToRpm;

      BvdCar.GearboxSpec gearbox = DEFAULT_GEARBOX_4;
      int ratioCount = script.getGearRatioCount();
      if (ratioCount == 3) {
         gearbox = DEFAULT_GEARBOX_3;
      } else if (ratioCount == 5) {
         gearbox = DEFAULT_GEARBOX_5;
      }

      InventoryItem gearboxItem = null;
      InventoryItem converterItem = null;
      if (engineBox != null) {
         gearboxItem = engineBox.getFirstTag(tagGearbox);
         converterItem = engineBox.getFirstTag(tagConverter);
      }

      if (gearboxItem != null) {
         String key = gearboxItem.getFullType();
         key = key.substring(0, key.length() - 2);
         BvdCar.GearboxSpec found = gearboxSpecs.get(key);
         if (found != null) {
            gearbox = found;
         }
      }

      BvdCar.ConverterSpec converter = DEFAULT_CONVERTER;
      if (converterItem != null) {
         String key = converterItem.getFullType();
         key = key.substring(0, key.length() - 2);
         BvdCar.ConverterSpec found = converterSpecs.get(key);
         if (found != null) {
            converter = found;
         }
      }

      // Automatic gear pick: climb while the geared wheel RPM is below the
      // shift point (with hysteresis when shifting down), then bias one gear
      // higher if we are clearly cruising (low overrev) and have headroom.
      int gear;
      for (gear = 1; gear < gearbox.gearCount; gear++) {
         float hysteresis = this.heldGear > gear ? 500.0F : 0.0F;
         if (wheelRpm * gearbox.ratios[gear] < shiftRpm - hysteresis) {
            break;
         }
      }

      this.heldGear = gear;
      if (gear >= 1 && gear < gearbox.gearCount && wheelRpm * gearbox.ratios[gear + 1] > shiftRpm * 0.5 && this.overrev < 0.5F) {
         gear++;
      }

      // A real automatic also shifts on engine speed. While the wheels spin the road speed stays low, so the
      // road-speed pick above stays in a low gear and the engine runs to redline. Take one gear up while the
      // engine is at its shift point and the wheels are slipping, and hold it until the engine has calmed down
      // or the slip is gone, so it does not hunt between gears.
      float engineRpmNow = (float)this.cc.vehicleObject.getEngineSpeed();
      if (this.burnout > SLIP_UPSHIFT_BURNOUT && engineRpmNow >= shiftRpm * 0.98F) {
         this.slipUpshift = true;
      } else if (this.burnout <= 0.0F || engineRpmNow < shiftRpm * 0.75F) {
         this.slipUpshift = false;
      }
      if (this.slipUpshift && gear >= 1 && gear < gearbox.gearCount) {
         gear++;
      }

      if (this.manualGearbox && bridge != null) {
         gear = bridge.rawgetInt("forceGear");
         if (this.shiftDownEdge == 1) {
            this.shiftDownEdge = 2;
            gear--;
         }

         if (this.shiftUpEdge == 1) {
            this.shiftUpEdge = 2;
            gear++;
         }

         if (this.autoReverseEnabled) {
            if (gear < 1) {
               gear = 1;
            }
         } else if (gear < 0) {
            gear = 0;
         }

         if (gear > gearbox.gearCount) {
            gear = gearbox.gearCount;
         }

         bridge.rawset("forceGear", Integer.valueOf(gear).doubleValue());
         if (this.reversing) {
            bridge.rawset("forceGear", Integer.valueOf(1).doubleValue());
         }
      }

      if (this.reversing) {
         gear = 0;
      }

      wheelRpm *= gearbox.ratios[gear];
      this.cc.vehicleObject.transmissionNumber = GEAR_LABELS[gear];

      // The engine power is used as it is. The realism option's extra gain is applied to the vehicle
      // scripts for every vehicle, registered or not (BVD_Overhaul.lua), not here for registered ones only.
      float powerUnit = this.cc.vehicleObject.getEnginePower() / 10.0F;

      float engineRpm = (float)this.cc.vehicleObject.getEngineSpeed();
      float engineTorqueDelta = 0.0F;
      float powerKnob = this.getSandboxOption("BetterVehicleDynamics.EnginePower", 1.0F);
      if (powerKnob > 5.0F) {
         powerKnob = 5.0F;
      }

      float ratedTorque = powerUnit * powerKnob * 4500.0F / redline;
      float flywheelInertia = ratedTorque * 1.0E-4F;
      if (engineBox != null) {
         InventoryItem flywheel = engineBox.getFirstTag(tagFlywheel);
         if (flywheel != null) {
            float size = flywheel.getScriptItem().getMaxItemSize();
            if (size > 0.0F) {
               flywheelInertia /= size;
            }
         }
      }

      flywheelInertia = Math.max(0.001F, flywheelInertia);
      if (this.cc.vehicleObject.isEngineRunning()) {
         if (engineRpm < 400.0F) {
            engineRpm = 400.0F;
            this.cc.vehicleObject.setEngineSpeed(engineRpm);
         }

         this.updateIdle(dt, enginePart);
         float signedSpeed = this.cc.vehicleObject.getCurrentSpeedKmHour() * BaseVehicle.getFakeSpeedModifier();
         float reverseCap = this.getSandboxOption("BetterVehicleDynamics.ReverseTopSpeed", 25.0F);
         if (this.reversing && signedSpeed < -reverseCap) {
            this.cc.vehicleObject.throttle = Math.min(this.cc.vehicleObject.throttle, (signedSpeed + reverseCap + 5.0F) / 5.0F);
         }

         float curveTop = Math.min(Math.max(1.0F - (engineRpm - redline) / 1000.0F, 0.0F), 1.0F);
         curveTop = (float)(curveTop * Math.min(Math.max((double)(engineRpm / redline * 2.0F), 0.2), 1.0));
         engineTorqueDelta = this.cc.vehicleObject.throttle * curveTop * ratedTorque;
         engineTorqueDelta = (float)(engineTorqueDelta - ratedTorque * 0.35F * this.cc.vehicleObject.getEngineSpeed() / redline);
      }

      // Torque-converter slip: clamp(0..3) of how far we are above the lockup
      // band, scaled down by how well the geared wheel speed already tracks
      // engine RPM (locked at high coupling). LowSpeedGrunt multiplies the
      // low-speed/converter-coupling response.
      float couple = Math.max(0.0F, Math.min(3.0F, (engineRpm - (converter.lockupRpm - converter.lockupRange)) / converter.lockupRange));
      float gearedWheelRpm = this.drivenWheelSpeed * gearbox.ratios[gear] * speedToRpm;
      if (gear == 0) {
         gearedWheelRpm = -gearedWheelRpm;
      }

      gearedWheelRpm = Math.max(0.0F, gearedWheelRpm);
      float coupleRatio = gearedWheelRpm / Math.max(engineRpm, 1.0F);
      coupleRatio = Math.min(coupleRatio, 1.0F);
      couple -= coupleRatio;
      couple *= Math.max(0.0F, Math.min(1.0F, (1.0F - coupleRatio) * 5.0F));

      float converterHealth = 1.2F;
      if (engineBox != null) {
         converterHealth = 0.0F;
         if (gearboxItem != null) {
            converterHealth = Math.min(1.2F, gearboxItem.getCondition() / 50.0F);
            converterHealth = (float)(converterHealth * Math.min(1.0, gearboxItem.getFluidContainer().getFilledRatio() * 2.0));
         }

         if (converterItem != null) {
            converterHealth *= Math.min(1.0F, converterItem.getCondition() / 50.0F);
         } else {
            converterHealth = 0.0F;
         }
      }

      couple *= converterHealth;
      couple = Math.min(Math.max(couple, 0.0F), 1.2F);
      float lockMix = Math.min(Math.max(coupleRatio * 1.1F, 0.0F), 1.0F);
      lockMix = 1.0F - lockMix;
      float gruntKnob = this.getSandboxOption("BetterVehicleDynamics.LowSpeedGrunt", 2.5F);
      lockMix = lockMix * (gruntKnob - 1.0F) + 1.0F;

      float wheelTorque = ratedTorque * couple * lockMix * gearbox.ratios[gear] * speedToRpm * 0.05F;

      // Optional load-response: a heavily laden vehicle bogs down off the line.
      // baseMass is the BVD reference mass for this script if the Lua side has
      // published one (vehicleData channel), else the script's own mass. The
      // whole effect is gated behind a published, enabled loadResponse policy
      // whose threshold the current laden ratio actually exceeds -- so with
      // nothing published (today's only state) p stays 0 and wheelTorque is
      // untouched, leaving the empty-vehicle force math byte-identical.
      float baseMass = script.getMass();
      KahluaTableImpl loadBridge = this.bvdBridge();
      if (loadBridge != null) {
         Object rawVehData = loadBridge.rawget("vehicleData");
         if (rawVehData instanceof KahluaTableImpl) {
            Object rawRow = ((KahluaTableImpl)rawVehData).rawget(script.getFullType());
            if (rawRow instanceof KahluaTableImpl) {
               float refMass = bridgeFieldOr((KahluaTableImpl)rawRow, "mass_kg", -1.0F);
               if (refMass > 0.0F) {
                  baseMass = refMass;
               }
            }
         }
      }

      float ladenRatio = this.cc.vehicleObject.getMass() / Math.max(1.0F, baseMass);
      ladenRatio = Math.min(Math.max(ladenRatio, 1.0F), 3.0F);
      this.ladenRatioOut = ladenRatio;
      float loadPenalty = 0.0F;
      Object rawLoadResponse = (loadBridge == null) ? null : loadBridge.rawget("loadResponse");
      KahluaTableImpl lr = (rawLoadResponse instanceof KahluaTableImpl)
         ? (KahluaTableImpl)rawLoadResponse
         : null;
      if (lr != null && lr.rawgetBool("enabled")) {
         // Every numeric field is read via bridgeFieldOr with a NO-OP-safe
         // default, NOT bare rawgetFloat (which returns the -1 miss
         // sentinel). A partially-formed/typo'd policy table therefore
         // degrades to "no penalty" instead of inverting the sign of the
         // torque multiplier. threshold>=1.1 ⇒ ladenRatio (clamped <=3, but
         // a missing table means an unintended policy) keeps the block from
         // doing harm; maxPenalty=0 / easeBySpeedKmh=0 also yield zero.
         float threshold = bridgeFieldOr(lr, "threshold", 1.1F);
         if (ladenRatio > threshold) {
            float fullAt = bridgeFieldOr(lr, "fullAt", 1.2F);
            float span = fullAt - threshold;
            float ramp = (span <= 0.0F) ? 1.0F : Math.min(Math.max((ladenRatio - threshold) / span, 0.0F), 1.0F);
            loadPenalty = bridgeFieldOr(lr, "maxPenalty", 0.0F) * ramp;
            float easeBy = bridgeFieldOr(lr, "easeBySpeedKmh", 0.0F);
            float speedKmh = Math.abs(this.cc.vehicleObject.getCurrentSpeedKmHour());
            float fade = (easeBy <= 0.0F) ? 0.0F : Math.min(Math.max(1.0F - speedKmh / easeBy, 0.0F), 1.0F);
            loadPenalty *= fade;
            // Defence-in-depth: clamped to [0,1] so the delivered force can
            // only ever be reduced, never amplified. NOT applied here -- a
            // pre-clamp torque cut is swallowed when launch torque exceeds
            // gripLimit and re-clamps to the identical cap. It is applied to
            // the final engineForce after the grip clamp instead.
            loadPenalty = Math.max(0.0F, Math.min(1.0F, loadPenalty));
         }
      }
      this.loadPenaltyOut = loadPenalty;

      float gripLimit = this.cc.vehicleObject.getMass() * 2.0F * this.gripFactor * this.getSandboxOption("BetterVehicleDynamics.GripLevel", 1.0F);
      this.lastGripLimit = gripLimit;
      float forceScale = 1.0F;
      float brakeToTorque = 50.0F;
      wheelTorque -= this.cc.brakingForce * brakeToTorque;
      this.burnout = 0.0F;
      float vehSpeed = this.cc.vehicleObject.getCurrentSpeedKmHour() * BaseVehicle.getFakeSpeedModifier();
      if (gear == 0) {
         this.drivenWheelSpeed -= (wheelTorque - gripLimit) * dt * 0.02F;
         this.drivenWheelSpeed = Math.min(this.drivenWheelSpeed, vehSpeed);
         this.burnout = Math.max(vehSpeed - this.drivenWheelSpeed - 3.0F, 0.0F);
      } else {
         this.drivenWheelSpeed += (wheelTorque - gripLimit) * dt * 0.02F;
         this.drivenWheelSpeed = Math.max(this.drivenWheelSpeed, vehSpeed);
         this.burnout = Math.max(this.drivenWheelSpeed - vehSpeed - 3.0F, 0.0F);
      }

      if (wheelTorque > gripLimit) {
         forceScale = gripLimit / Math.max(1.0F, wheelTorque);
         wheelTorque = gripLimit;
      }

      if (gear == 0) {
         this.burnout = -this.burnout;
      }

      if (GameClient.client && this.cc.vehicleObject.getCurrentSpeedKmHour() >= ServerOptions.instance.speedLimit.getValue()) {
         wheelTorque = 0.0F;
      }

      this.updateTireStats();
      this.publishComputedState();
      this.bvdPruneSkidMarks();
      this.bvdStabilityGuard();
      this.applyDrag(dt);
      engineTorqueDelta -= ratedTorque * couple * Math.max(forceScale, SLIP_ENGINE_LOAD_FLOOR);
      if (wheelTorque < 0.0F) {
         this.cc.brakingForce = -wheelTorque / brakeToTorque;
         wheelTorque = 0.0F;
      }

      this.cc.engineForce = wheelTorque;
      // Load-response: bog a laden vehicle off the line by attenuating the
      // DELIVERED force, after the grip-limit clamp so it cannot be absorbed
      // by it. loadPenalty is 0 unless an enabled loadResponse policy and an
      // over-threshold laden ratio set it, so the empty / no-policy / not-yet-
      // published path stays byte-identical to stock.
      this.cc.engineForce *= (1.0F - loadPenalty);
      this.cc.vehicleObject.addEngineSpeed(engineTorqueDelta / flywheelInertia * dt);
      this.cc.vehicleObject.setEngineSpeed(Math.max(200.0, this.cc.vehicleObject.getEngineSpeed()));
      if (this.cc.vehicleObject.getEngineSpeed() != this.cc.vehicleObject.getEngineSpeed()) {
         this.cc.vehicleObject.setEngineSpeed(200.0);
      }

      if (this.cc.engineForce != this.cc.engineForce) {
         this.cc.engineForce = 0.0F;
      }

      if (gear == 0) {
         this.cc.engineForce = -this.cc.engineForce;
      }

      this.updateSkidding(false);
      if (this.tunableSteering) {
         this.updateSteeringTunable(engineBox, script, dt);
      } else {
         this.updateSteeringStock(script);
      }

      BvdCar.BulletVariables bv = bulletVariables.set(this.cc.vehicleObject, this.cc.engineForce, this.cc.brakingForce, this.steerAngle);
      this.checkTire(bv);
      this.cc.engineForce = bv.engineForce;
      this.cc.brakingForce = bv.brakingForce;
      this.steerAngle = bv.vehicleSteering;
      this.cc.vehicleObject.setCurrentSteering(this.steerAngle);
      this.cc.vehicleObject.setBraking(this.isBreak);
      if (!GameServer.server) {
         this.checkShouldBeActive();
         Bullet.controlVehicle(
            this.cc.vehicleObject.vehicleId,
            this.cc.engineForce * BvdWorld.massScaler,
            this.cc.brakingForce,
            this.steerAngle
         );
         boolean throttleStart = this.getSandboxOptionBoolean("BetterVehicleDynamics.ThrottleStart", true);
         if ((this.isGas || this.isGasR) && this.cc.vehicleObject.getEngineState() == engineStateTypes.Idle && !this.engineStartingFromKeyboard && throttleStart) {
            this.engineStartingFromKeyboard = true;
            if (GameClient.client) {
               Boolean haveKey = this.cc.vehicleObject.getDriver().getInventory().haveThisKeyId(this.cc.vehicleObject.getKeyId()) != null
                  ? Boolean.TRUE
                  : Boolean.FALSE;
               GameClient.instance.sendClientCommandV((IsoPlayer)this.cc.vehicleObject.getDriver(), "vehicle", "startEngine", new Object[]{"haveKey", haveKey});
            } else if (!GameClient.client && !GameServer.server) {
               Boolean haveKey = this.cc.vehicleObject.getDriver().getInventory().haveThisKeyId(this.cc.vehicleObject.getKeyId()) != null
                  ? Boolean.TRUE
                  : Boolean.FALSE;
               this.cc.vehicleObject.tryStartEngine(haveKey);
            } else {
               this.cc.vehicleObject.tryStartEngine();
            }
         }

         if (this.engineStartingFromKeyboard && !this.isGas && !this.isGasR) {
            this.engineStartingFromKeyboard = false;
         }
      }

      if (this.cc.vehicleObject.getEngineState() != engineStateTypes.Running) {
         this.cc.acceleratorOn = false;
         if (!GameServer.server && this.cc.vehicleObject.getCurrentSpeedKmHour() > 5.0F && script.getWheelCount() > 0) {
            Bullet.controlVehicle(this.cc.vehicleObject.vehicleId, 0.0F, this.cc.brakingForce, this.steerAngle);
         } else {
            this.park();
         }
      }
   }

   public void updateTrailer() {
      this.loadLUATables();
      BaseVehicle towedBy = this.cc.vehicleObject.getVehicleTowedBy();
      if (towedBy == null) {
         return;
      }
      if (GameServer.server) {
         if (towedBy.getDriver() == null && this.cc.vehicleObject.getDriver() != null) {
            this.cc.vehicleObject.addPointConstraint(null, towedBy, this.cc.vehicleObject.getTowAttachmentSelf(), towedBy.getTowAttachmentSelf());
         }
         return;
      }

      this.cc.speed = this.cc.vehicleObject.getCurrentSpeedKmHour();
      this.isGas = false;
      this.isGasR = false;
      this.isBreak = false;
      this.wasGas = false;
      this.wasGasR = false;
      this.wasBreaking = false;
      this.cc.vehicleObject.throttle = 0.0F;
      if (towedBy.getDriver() == null && this.cc.vehicleObject.getDriver() != null && !GameClient.client) {
         this.cc.vehicleObject.addPointConstraint(null, towedBy, this.cc.vehicleObject.getTowAttachmentSelf(), towedBy.getTowAttachmentSelf());
         return;
      }

      this.checkShouldBeActive();
      this.cc.engineForce = 0.0F;
      this.cc.brakingForce = 0.0F;
      this.steerAngle = 0.0F;
      boolean isTrailer = this.cc.vehicleObject.getScriptName().contains("Trailer");
      float dt = GameTime.getInstance().getRealworldSecondsSinceLastUpdate();
      this.updateTireStats();
      this.applyDrag(dt);
      if (!isTrailer) {
         this.steerAngle = 0.0F;
         Vector2f toTower = new Vector2f();
         toTower.x = towedBy.getX() - this.cc.vehicleObject.getX();
         toTower.y = towedBy.getY() - this.cc.vehicleObject.getY();
         Vector3f facing = new Vector3f();
         this.cc.vehicleObject.getForwardVector(facing);
         float yawErr = (float)Math.atan2(toTower.x, toTower.y) - (float)Math.atan2(facing.x, facing.z);
         if (yawErr > Math.PI) {
            yawErr = (float)(yawErr - (Math.PI * 2));
         }

         if (yawErr < -Math.PI) {
            yawErr = (float)(yawErr + (Math.PI * 2));
         }

         VehicleScript script = this.cc.vehicleObject.getScript();
         float clamp = script.getSteeringClamp(this.cc.speed);
         this.steerAngle = PZMath.clamp(yawErr * 0.3F, -clamp, clamp);
         if (this.cc.vehicleObject.getCurrentSpeedKmHour() < 1.0F) {
            this.steerAngle = 0.0F;
         }

         boolean keylessTow = this.getSandboxOptionBoolean("BetterVehicleDynamics.KeylessTow", true);
         if (!(this.cc.vehicleObject.isKeysInIgnition() | this.cc.vehicleObject.isHotwired() | keylessTow)) {
            this.cc.brakingForce = 500.0F;
         }

         this.updateSkidding(true);
      }

      Bullet.controlVehicle(this.cc.vehicleObject.vehicleId, this.cc.engineForce, this.cc.brakingForce, this.steerAngle);
   }

   private void updateRegulator(float dt) {
      if (this.regulatorTimer > 0.0F) {
         this.regulatorTimer -= dt;
      }

      if (this.cc.clientControls.shift) {
         if (this.cc.clientControls.forward && this.regulatorTimer <= 0.0F) {
            if (this.cc.vehicleObject.getRegulatorSpeed() < this.cc.vehicleObject.getMaxSpeed() + 20.0F
               && (!this.cc.vehicleObject.isRegulator() && this.cc.vehicleObject.getRegulatorSpeed() == 0.0F || this.cc.vehicleObject.isRegulator())) {
               if (this.cc.vehicleObject.getRegulatorSpeed() == 0.0F
                  && this.cc.vehicleObject.getCurrentSpeedForRegulator() != this.cc.vehicleObject.getRegulatorSpeed()) {
                  this.cc.vehicleObject.setRegulatorSpeed(this.cc.vehicleObject.getCurrentSpeedForRegulator());
               } else {
                  this.cc.vehicleObject.setRegulatorSpeed(this.cc.vehicleObject.getRegulatorSpeed() + 1.0F);
               }
            }

            if (!this.cc.vehicleObject.isRegulator()) {
               this.cc.vehicleObject.setRegulatorSpeed((float)Math.floor(this.cc.vehicleObject.getCurrentSpeedKmHour() * BaseVehicle.getFakeSpeedModifier()));
            }

            this.cc.vehicleObject.setRegulator(true);
            if (this.cc.vehicleObject.getRegulatorSpeed() <= 0.0F) {
               this.cc.vehicleObject.setRegulatorSpeed(0.0F);
               this.cc.vehicleObject.setRegulator(false);
            }

            this.regulatorTimer += 0.1F;
         } else if (this.cc.clientControls.backward) {
            this.regulatorTimer = 0.0F;
            this.cc.vehicleObject.setRegulatorSpeed((float)Math.ceil(this.cc.vehicleObject.getCurrentSpeedKmHour() * BaseVehicle.getFakeSpeedModifier()));
            this.cc.vehicleObject.setRegulator(true);
            if (this.cc.vehicleObject.getRegulatorSpeed() <= 0.0F) {
               this.cc.vehicleObject.setRegulatorSpeed(0.0F);
               this.cc.vehicleObject.setRegulator(false);
            }
         }
      } else if (this.isGasR || this.isBreak) {
         this.cc.vehicleObject.setRegulator(false);
      }
   }

   // --- Skidding sound / rear-wheel spin -----------------------------------

   // Drive the rear-wheel visual spin from the burnout amount and play the
   // skid loop when the rear is sliding (offroad/snow uses a different clip).
   private void updateSkidding(boolean towed) {
      // Towed-skid gate. "TowedSkid" is not a declared sandbox option in the
      // BVD taxonomy; it is a client mod-options tickbox surfaced through the
      // bridge, so the bridge value is authoritative. The no-bridge degenerate
      // path keeps the historical default (towed skid off) without a redundant
      // getSandboxOptionBoolean lookup that would only ever return this same
      // fallback for an undeclared key.
      boolean towedSkidEnabled = false;
      float skidVolume = 0.5F;
      KahluaTableImpl bridge = this.bvdBridge();
      if (bridge != null) {
         towedSkidEnabled = bridge.rawgetBool("towSkidding");
         skidVolume = bridge.rawgetFloat("skidVolume");
      }

      skidVolume *= Core.getInstance().getOptionSoundVolume() / 10.0F;
      // Parity-safe clamp: no-op when skidVolume is in [0,1]; prevents a
      // pathological negative (e.g. bridge rawgetFloat returning -1 on a missing
      // key) from silently muting via setVolume(..., negative).
      skidVolume = Math.max(0.0F, Math.min(1.0F, skidVolume));
      if ((!towed || towedSkidEnabled) && this.cc.vehicleObject.getScript().getMechanicType() != 4) {
         float dt = GameTime.getInstance().getRealworldSecondsSinceLastUpdate();
         float slip = 0.0F;

         for (int i = 2; i < 4; i++) {
            slip = (float)(slip + Math.min(Math.max(1.0F - this.cc.vehicleObject.wheelInfo[i].skidInfo - 0.3, 0.0), 0.5));
         }

         slip += Math.abs(this.burnout * 0.1F);
         slip = Math.max(Math.min(slip, 1.0F), 0.0F);
         float[] spinDelta = this.skidSpinDelta;
         spinDelta[0] = this.cc.vehicleObject.wheelInfo[2].rotation - this.rearSpinAngleLast[0];
         spinDelta[1] = this.cc.vehicleObject.wheelInfo[3].rotation - this.rearSpinAngleLast[1];
         this.rearSpinAngleLast[0] = this.cc.vehicleObject.wheelInfo[2].rotation;
         this.rearSpinAngleLast[1] = this.cc.vehicleObject.wheelInfo[3].rotation;
         boolean braking = this.cc.clientControls.brake;
         BaseVehicle towedByVehicle = this.cc.vehicleObject.getVehicleTowedBy();
         if (towedByVehicle != null) {
            braking = this.cc.brakingForce > 1.0F;
         }

         if (slip > 0.2 && braking) {
            spinDelta[0] = 0.0F;
            spinDelta[1] = 0.0F;
         } else {
            spinDelta[0] += this.burnout * dt * 1.0F;
            spinDelta[1] += this.burnout * dt * 1.0F;
         }

         this.rearSpinAngle[0] = this.rearSpinAngle[0] + spinDelta[0];
         this.rearSpinAngle[1] = this.rearSpinAngle[1] + spinDelta[1];

         for (int i = 2; i < 4; i++) {
            this.cc.vehicleObject.wheelInfo[i].rotation = this.rearSpinAngle[i - 2];
            if (this.rearSpinAngle[i - 2] > 1000.0F) {
               this.rearSpinAngle[i - 2] = 0.0F;
            }

            if (this.rearSpinAngle[i - 2] < -1000.0F) {
               this.rearSpinAngle[i - 2] = 0.0F;
            }
         }

         if (this.cc.vehicleObject.isEngineRunning() || towedByVehicle != null && slip > 0.2) {
            boolean roughSurface = this.cc.vehicleObject.isDoingOffroad();
            roughSurface |= ClimateManager.getInstance().getSnowStrength() > 0.5F;
            if (this.offroadSkidLast != roughSurface) {
               this.offroadSkidLast = roughSurface;
               if (this.cc.vehicleObject.ramSound != 0L) {
                  this.cc.vehicleObject.stopSound(this.cc.vehicleObject.ramSound);
                  this.cc.vehicleObject.ramSound = 0L;
               }
            }

            if (this.cc.vehicleObject.ramSound == 0L) {
               // v0.1.8: switched from vanilla "VehicleSkid" to the BVD custom
               // event "BVD_SkidMP" with loop=true. Each client computes its
               // own wheelInfo[i].skidInfo from local physics and drives its
               // own emitter start/stop — no cross-network Start/Tick/Stop
               // commands, no heartbeat, no watchdog. Replaces the previous
               // Lua heartbeat model (BVD_SkidSound.lua + BVD_SkidSync_Server)
               // whose MP looping bugs surfaced repeatedly (v0.1.3 → v0.1.6
               // each patched a different symptom of the same underlying
               // shared-state coupling). When the SkidSound sandbox option
               // is off, fall back to vanilla "VehicleSkid" so vehicles
               // still get base audio feedback.
               boolean useBvdSound = this.getSandboxOptionBoolean(
                  "BetterVehicleDynamics.SkidSound", true);
               String skidEvent = useBvdSound ? "BVD_SkidMP" : "VehicleSkid";
               this.cc.vehicleObject.ramSound = this.cc.vehicleObject.playSoundImpl(skidEvent, (IsoObject)null);
            }

            if (towed) {
               skidVolume = (float)(skidVolume * 0.8);
            }

            // Vanilla scales skid volume linearly by raw wheel-slip, which on
            // B42.18 stays so low (often < 0.1) that the stock CarSkiddingLoud
            // event is effectively inaudible. Lift it with a sqrt response and
            // a gain so a real slide is clearly heard -- still silent at slip
            // 0, still clamped to 1.0, still scaled by the user's master sound
            // volume (already folded into skidVolume above).
            float bvdVol = Math.min(1.0F, (float)Math.sqrt(Math.min(1.0F, slip)) * skidVolume * 2.5F);
            this.cc.vehicleObject.getEmitter().setVolume(this.cc.vehicleObject.ramSound, bvdVol);
         } else if (this.cc.vehicleObject.ramSound != 0L) {
            this.cc.vehicleObject.stopSound(this.cc.vehicleObject.ramSound);
            this.cc.vehicleObject.ramSound = 0L;
         }
      } else if (this.cc.vehicleObject.ramSound != 0L) {
         this.cc.vehicleObject.stopSound(this.cc.vehicleObject.ramSound);
         this.cc.vehicleObject.ramSound = 0L;
      }
   }

   public float getVehicleSteering() {
      return this.steerAngle;
   }

   public void control_NoControl() {
      if (this.cc.vehicleObject.getEngine() == null) {
         this.cc.vehicleObject.transmissionNumber = TransmissionNumber.N;
         this.cc.engineForce = 0.0F;
         this.cc.brakingForce = 10.0F;
         return;
      }

      float fps = GameTime.getInstance().getMultiplier() / 0.8F;
      if (!this.cc.vehicleObject.isEngineRunning()) {
         if (this.cc.vehicleObject.getEngineSpeed() > 0.0) {
            this.cc.vehicleObject.setEngineSpeed(Math.max(this.cc.vehicleObject.getEngineSpeed() - 50.0F * fps, 0.0));
         }
      } else if (this.cc.vehicleObject.getEngineSpeed() > this.cc.vehicleObject.getScript().getEngineIdleSpeed()) {
         if (!this.cc.vehicleObject.isRegulator()) {
            this.cc.vehicleObject.addEngineSpeed(-20.0F * fps);
         }
      } else {
         this.cc.vehicleObject.addEngineSpeed(20.0F * fps);
      }

      if (!this.cc.vehicleObject.isRegulator()) {
         this.cc.vehicleObject.transmissionNumber = TransmissionNumber.N;
      }

      this.cc.engineForce = 0.0F;
      if (this.cc.vehicleObject.getEngineSpeed() > 1000.0) {
         this.cc.brakingForce = 15.0F;
      } else {
         this.cc.brakingForce = 10.0F;
      }
   }

   private void updateBackSignal() {
      if (this.isGasR && this.cc.vehicleObject.isEngineRunning() && this.cc.vehicleObject.hasBackSignal() && !this.cc.vehicleObject.isBackSignalEmitting()) {
         if (GameClient.client) {
            GameClient.instance.sendClientCommandV((IsoPlayer)this.cc.vehicleObject.getDriver(), "vehicle", "onBackSignal", "state", "start");
         } else {
            this.cc.vehicleObject.onBackMoveSignalStart();
         }
      }

      if (!this.isGasR && this.cc.vehicleObject.isBackSignalEmitting()) {
         if (GameClient.client) {
            GameClient.instance.sendClientCommandV((IsoPlayer)this.cc.vehicleObject.getDriver(), "vehicle", "onBackSignal", "state", "stop");
         } else {
            this.cc.vehicleObject.onBackMoveSignalStop();
         }
      }
   }

   private void updateBrakeLights() {
      if (this.isBreak) {
         if (this.cc.vehicleObject.getStoplightsOn()) {
            return;
         }

         if (GameClient.client) {
            GameClient.instance.sendClientCommandV((IsoPlayer)this.cc.vehicleObject.getDriver(), "vehicle", "setStoplightsOn", "on", Boolean.TRUE);
         }

         if (!GameServer.server) {
            this.cc.vehicleObject.setStoplightsOn(true);
         }
      } else {
         if (!this.cc.vehicleObject.getStoplightsOn()) {
            return;
         }

         if (GameClient.client) {
            GameClient.instance.sendClientCommandV((IsoPlayer)this.cc.vehicleObject.getDriver(), "vehicle", "setStoplightsOn", "on", Boolean.FALSE);
         }

         if (!GameServer.server) {
            this.cc.vehicleObject.setStoplightsOn(false);
         }
      }
   }

   private boolean delayCommandWhileDrunk(boolean command) {
      this.drunkDelayCommandTimer = this.drunkDelayCommandTimer + zombie.GameTime.getInstance().getMultiplier();
      if (Rand.AdjustForFramerate(4 * this.cc.vehicleObject.getDriver().getMoodles().getMoodleLevel(MoodleType.DRUNK)) < this.drunkDelayCommandTimer) {
         this.drunkDelayCommandTimer = 0.0F;
         return true;
      } else {
         return false;
      }
   }

   private float delayCommandWhileDrunk(float steering) {
      this.drunkDelayCommandTimer = this.drunkDelayCommandTimer + zombie.GameTime.getInstance().getMultiplier();
      if (Rand.AdjustForFramerate(4 * this.cc.vehicleObject.getDriver().getMoodles().getMoodleLevel(MoodleType.DRUNK)) < this.drunkDelayCommandTimer) {
         this.drunkDelayCommandTimer = 0.0F;
         return steering;
      } else {
         return 0.0F;
      }
   }

   private void checkTire(BvdCar.BulletVariables bv) {
      if (this.cc.vehicleObject.getPartById("TireFrontLeft") == null || this.cc.vehicleObject.getPartById("TireFrontLeft").getInventoryItem() == null) {
         bv.brakingForce = (float)(bv.brakingForce / 1.2);
         bv.engineForce = (float)(bv.engineForce / 1.2);
      }

      if (this.cc.vehicleObject.getPartById("TireFrontRight") == null || this.cc.vehicleObject.getPartById("TireFrontRight").getInventoryItem() == null) {
         bv.brakingForce = (float)(bv.brakingForce / 1.2);
         bv.engineForce = (float)(bv.engineForce / 1.2);
      }

      if (this.cc.vehicleObject.getPartById("TireRearLeft") == null || this.cc.vehicleObject.getPartById("TireRearLeft").getInventoryItem() == null) {
         bv.brakingForce = (float)(bv.brakingForce / 1.3);
         bv.engineForce = (float)(bv.engineForce / 1.3);
      }

      if (this.cc.vehicleObject.getPartById("TireRearRight") == null || this.cc.vehicleObject.getPartById("TireRearRight").getInventoryItem() == null) {
         bv.brakingForce = (float)(bv.brakingForce / 1.3);
         bv.engineForce = (float)(bv.engineForce / 1.3);
      }
   }

   void readPedals() {
      if (GameServer.server) {
         return;
      }
      

      this.pedalGas = 0.0F;
      this.pedalBrake = 0.0F;
      int joypad = this.cc.vehicleObject.getJoypad();
      if (joypad != -1) {
         boolean rt = JoypadManager.instance.isRTPressed(joypad);
         boolean lt = JoypadManager.instance.isLTPressed(joypad);
         boolean bBtn = JoypadManager.instance.isBPressed(joypad);
         if (this.shiftDownEdge == 0) {
            this.shiftDownEdge = JoypadManager.instance.isLBPressed(joypad) ? 1 : 0;
         } else if (this.shiftDownEdge == 2) {
            this.shiftDownEdge = JoypadManager.instance.isLBPressed(joypad) ? 2 : 0;
         }

         if (this.shiftUpEdge == 0) {
            this.shiftUpEdge = JoypadManager.instance.isRBPressed(joypad) ? 1 : 0;
         } else if (this.shiftUpEdge == 2) {
            this.shiftUpEdge = JoypadManager.instance.isRBPressed(joypad) ? 2 : 0;
         }

         if (this.joystickPedalAxis) {
            if (JoypadManager.instance.getMovementAxisY(joypad) < 0.0F) {
               this.pedalGas = -JoypadManager.instance.getMovementAxisY(joypad);
            } else {
               this.pedalBrake = JoypadManager.instance.getMovementAxisY(joypad);
            }
         } else {
            byte gasAxis = 5;
            if (GameWindow.GameInput.getAxisCount(joypad) > gasAxis) {
               this.pedalGas = GameWindow.GameInput.getAxisValue(joypad, gasAxis) / 2.0F + 0.5F;
            }

            byte brakeAxis = 4;
            if (GameWindow.GameInput.getAxisCount(joypad) > brakeAxis) {
               this.pedalBrake = GameWindow.GameInput.getAxisValue(joypad, brakeAxis) / 2.0F + 0.5F;
            }
         }
      }

      
   }

   public void park() {
      if (this.cc.vehicleObject.isEngineRunning()) {
         float idleDt = GameTime.getInstance().getRealworldSecondsSinceLastUpdate();
         VehiclePart enginePart = this.cc.vehicleObject.getPartById("Engine");
         this.cc.vehicleObject.throttle = 0.0F;
         this.updateIdle(idleDt, enginePart);
         if (this.cc.vehicleObject.getEngine() != null) {
            this.cc.vehicleObject.addEngineSpeed((this.cc.vehicleObject.throttle - 0.1F) * idleDt * 5000.0F);
         }
      }

      BvdCar.VehicleSpec spec = vehicleSpecs.get(this.cc.vehicleObject.getScript().getFullType());
      float dt = GameTime.getInstance().getRealworldSecondsSinceLastUpdate();
      this.updateAudio(dt, spec);
      if (this.cc.vehicleObject.ramSound != 0L) {
         this.cc.vehicleObject.stopSound(this.cc.vehicleObject.ramSound);
         this.cc.vehicleObject.ramSound = 0L;
      }

      if (!GameServer.server && this.cc.vehicleObject.getScript().getWheelCount() > 0) {
         Bullet.controlVehicle(this.cc.vehicleObject.vehicleId, 0.0F, Math.max(2.5F, this.cc.vehicleObject.getBrakingForce()), 0.0F);
      }

      this.isGas = this.wasGas = false;
      this.isGasR = this.wasGasR = false;
      this.cc.clientControls.reset();
      this.cc.vehicleObject.transmissionNumber = TransmissionNumber.N;
      if (this.cc.vehicleObject.getVehicleTowing() != null) {
         this.cc.vehicleObject.getVehicleTowing().getController().park();
      }
   }

   protected boolean shouldBeActive() {
      if (this.cc.vehicleObject.physicActiveCheck != -1L) {
         return true;
      } else if (!this.cc.vehicleObject.isAtRest()) {
         return true;
      } else if (this.isPlayerDrivenVehicleNearby()) {
         return true;
      } else {
         BaseVehicle vehicleTowedBy = this.cc.vehicleObject.getVehicleTowedBy();
         if (vehicleTowedBy == null) {
            float engineForce = this.cc.vehicleObject.isEngineRunning() ? this.cc.engineForce : 0.0F;
            return Math.abs(engineForce) > 0.01F;
         } else {
            return vehicleTowedBy.getController() == null ? false : Hooks.shouldBeActive(vehicleTowedBy.getController());
         }
      }
   }

   public void checkShouldBeActive() {
      if (this.shouldBeActive()) {
         if (!this.cc.isEnable) {
            this.cc.vehicleObject.setPhysicsActive(true);
         }

         this.atRestTimer = 1.0F;
      } else if (this.cc.isEnable && this.cc.vehicleObject.isAtRest()) {
         if (this.atRestTimer > 0.0F) {
            this.atRestTimer = this.atRestTimer - zombie.GameTime.getInstance().getTimeDelta();
         }

         if (this.atRestTimer <= 0.0F) {
            this.cc.vehicleObject.setPhysicsActive(false);
         }
      }
   }

   private BaseVehicle getPlayerDrivenVehicleNearby() {
      int chunkX = PZMath.coorddivision(this.cc.vehicleObject.getXi(), 8);
      int chunkY = PZMath.coorddivision(this.cc.vehicleObject.getYi(), 8);
      Vector2f p1 = BaseVehicle.allocVector2f();
      Vector2f p2 = BaseVehicle.allocVector2f();
      BaseVehicle closest = null;
      float closestDistSq = Float.MAX_VALUE;

      for (int dy = -1; dy <= 1; dy++) {
         for (int dx = -1; dx <= 1; dx++) {
            IsoChunk chunk = IsoWorld.instance.currentCell.getChunk(chunkX + dx, chunkY + dy);
            if (chunk != null) {
               for (BaseVehicle vehicle : chunk.vehicles) {
                  if (vehicle != this.cc.vehicleObject && vehicle.getDriver() != null) {
                     float distSq = this.cc.vehicleObject.getClosestPointOnPoly(vehicle, p1, p2);
                     if (distSq < 9.0F && distSq < closestDistSq) {
                        closest = vehicle;
                        closestDistSq = distSq;
                     }
                  }
               }
            }
         }
      }

      BaseVehicle.releaseVector2f(p1);
      BaseVehicle.releaseVector2f(p2);
      return closest;
   }

   private boolean isPlayerDrivenVehicleNearby() {
      return this.getPlayerDrivenVehicleNearby() != null;
   }

   public static final class BulletVariables {
      private float engineForce;
      private float brakingForce;
      private float vehicleSteering;
      private BaseVehicle vehicle;

      private BvdCar.BulletVariables set(BaseVehicle vehicle, float engineForce, float brakingForce, float vehicleSteering) {
         this.vehicle = vehicle;
         this.engineForce = engineForce;
         this.brakingForce = brakingForce;
         this.vehicleSteering = vehicleSteering;
         return this;
      }
   }

